import { expect, test } from "@playwright/test";

import { loginAs } from "../support/auth";

test.describe("TC-003: Sort products by price, low to high", () => {
  test("should sort products by price low to high", async ({ page }) => {
    await loginAs(page, "standard_user");

    const sortDropdown = page.locator('[data-test="product-sort-container"]');
    await sortDropdown.selectOption("lohi");
    await expect(sortDropdown.locator("option:checked")).toHaveText("Price (low to high)");

    const prices = await page.locator('[data-test="inventory_item_price"]').allTextContents();
    const numericPrices = prices.map((price) => Number(price.replace("$", "")));
    expect(numericPrices).toEqual([...numericPrices].sort((a, b) => a - b));

    await expect(page.locator('[data-test="inventory_item_name"]').first()).toHaveText(
      "Sauce Labs Onesie",
    );
    await expect(page.locator('[data-test="inventory_item_price"]').first()).toHaveText("$7.99");
    await expect(page.locator('[data-test="inventory_item_name"]').last()).toHaveText(
      "Sauce Labs Fleece Jacket",
    );
    await expect(page.locator('[data-test="inventory_item_price"]').last()).toHaveText("$49.99");
  });
});

